        #include "monitoring_agent.h"

// 定义最大标签值长度
#define MAX_LABEL_VALUE_LENGTH 256
#define MAX_METRIC_NAME_LENGTH 128

// 监控指标结构体定义
typedef struct {
    char metric_name[MAX_METRIC_NAME_LENGTH];
    char label_value[MAX_LABEL_VALUE_LENGTH];
    int is_set;  // 标签是否已设置
} metric_info_t;

// 存储所有指标信息的数组
static metric_info_t metrics[100];  // 假设最多支持100个指标
static int metric_count = 0;

int set_metric_label(char* metric_name, char* label_value) {
    // 检查输入参数是否为空
    if (metric_name == NULL || label_value == NULL) {
        return -1;  // 参数错误
    }

    // 检查指标名称和标签值长度
    if (strlen(metric_name) >= MAX_METRIC_NAME_LENGTH || 
        strlen(label_value) >= MAX_LABEL_VALUE_LENGTH) {
        return -2;  // 长度超出限制
    }

    // 查找是否已存在该指标
    int existing_index = -1;
    for (int i = 0; i < metric_count; i++) {
        if (strcmp(metrics[i].metric_name, metric_name) == 0) {
            existing_index = i;
            break;
        }
    }

    // 如果指标已存在，更新其标签值
    if (existing_index != -1) {
        strncpy(metrics[existing_index].label_value, label_value, MAX_LABEL_VALUE_LENGTH - 1);
        metrics[existing_index].label_value[MAX_LABEL_VALUE_LENGTH - 1] = '\0';  // 确保字符串结束
        metrics[existing_index].is_set = 1;
        return 0;  // 成功更新
    }

    // 如果是新指标，添加到数组中
    if (metric_count < 100) {
        strncpy(metrics[metric_count].metric_name, metric_name, MAX_METRIC_NAME_LENGTH - 1);
        metrics[metric_count].metric_name[MAX_METRIC_NAME_LENGTH - 1] = '\0';  // 确保字符串结束

        strncpy(metrics[metric_count].label_value, label_value, MAX_LABEL_VALUE_LENGTH - 1);
        metrics[metric_count].label_value[MAX_LABEL_VALUE_LENGTH - 1] = '\0';  // 确保字符串结束

        metrics[metric_count].is_set = 1;
        metric_count++;
        return 0;  // 成功添加
    } else {
        return -3;  // 达到最大指标数量限制
    }
}
